      },
      {
        number: "#A-10263",
        date: "2025-05-12T12:00:00+03:00",
        total: 98.25,
        status: "delivered"
      }
    ];

    const statusContent = {
      delivered: {
        label: "تم التوصيل",
        icon: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"></circle><path d="m8 12 2.6 2.6L16.5 9"></path></svg>'
