        const status = statusContent[order.status];
        const amount = moneyFormatter.format(order.total).replace("SAR", "ر.س");

        return `
          <article class="order-card" data-status="${order.status}">
            <div class="order-head">
              <div>
                <p class="order-number">طلب رقم <bdi dir="ltr">${order.number}</bdi></p>
                <p class="order-date">
                  <bdi>${gregorianFormatter.format(date)}</bdi>
                  <span aria-hidden="true"> · </span>
                  <bdi>${hijriFormatter.format(date)}</bdi>
                </p>
              </div>
              <span class="status ${order.status}">${status.icon}<span>${status.label}</span></span>
            </div>
            <div class="order-body">
              <div>
                <p class="total-label">إجمالي الطلب</p>
                <p class="total"><bdi>${amount}</bdi></p>
              </div>
              <button class="details-button" type="button" aria-label="عرض تفاصيل الطلب ${order.number}">
                <span>التفاصيل</span>
                <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7"></path></svg>
              </button>
            </div>
          </article>
        `;
      }).join("");
    }

    document.getElementById("ordersIntro").textContent = pluralize(orderData.length);
    renderOrders();

    document.querySelectorAll(".filter").forEach(button => {
      button.addEventListener("click", () => {
        document.querySelectorAll(".filter").forEach(item => item.classList.remove("active"));
        button.classList.add("active");
        renderOrders(button.dataset.filter);
      });
    });
  </script>
</body>
